const payload = $input.first()?.json || {};
const body = payload.body || payload;
const raw = Array.isArray(body.products)
  ? body.products
  : Array.isArray(body.items)
    ? body.items
    : Array.isArray(body)
      ? body
      : body.product
        ? [body.product]
        : [];
const seen = new Set();
const output = [];
for (const row of raw) {
  const sku = String(row.sku || row.variant_sku || '').trim().toLowerCase();
  const handle = String(row.handle || row.product_handle || '').trim().toLowerCase();
  const productId = String(row.product_id || row.id || '').trim();
  const key = sku || handle || productId;
  if (!key || seen.has(key)) continue;
  seen.add(key);
  const title = String(row.title || row.name || '').trim();
  const description = String(row.description || row.body_html || row.body || '').replace(/<[^>]+>/g, ' ').trim();
  const tags = String(row.tags || '').trim();
  const vendor = String(row.vendor || '').trim();
  const productType = String(row.product_type || row.type || '').trim();
  const missingDescription = description.length < 40;
  const missingSeoTitle = title.length < 10 || title.length > 70;
  const needsEnrichment = missingDescription || missingSeoTitle;
  output.push({
    json: {
      enrich_id: 'CAT-' + $now.toFormat('yyyyLLdd-HHmmss') + '-' + String(output.length + 1).padStart(3, '0'),
      received_at: $now.toISO(),
      product_id: productId,
      sku,
      handle,
      title,
      description,
      tags,
      vendor,
      product_type: productType,
      missing_description: missingDescription,
      missing_seo_title: missingSeoTitle,
      needs_enrichment: needsEnrichment,
      enrichment_reason: [
        missingDescription ? 'empty_description' : '',
        missingSeoTitle ? 'title_seo_gap' : '',
      ].filter(Boolean).join(' | '),
      store_name: 'REPLACE_WITH_STORE_NAME',
      ai_prompt: [
        'Enrich this Shopify product for SEO and conversion.',
        'Store: REPLACE_WITH_STORE_NAME',
        'Title: ' + title,
        'Current description: ' + (description || '(empty)'),
        'Tags: ' + tags,
        'Vendor: ' + vendor,
        'Type: ' + productType,
        'SKU: ' + sku,
        'Needs: ' + (missingDescription ? 'full description' : '') + (missingSeoTitle ? ' SEO title' : ''),
      ].join('\n'),
    },
  });
}
if (!output.length) {
  return [{
    json: {
      enrich_id: 'CAT-' + $now.toFormat('yyyyLLdd-HHmmss') + '-000',
      received_at: $now.toISO(),
      product_id: '',
      sku: '',
      handle: '',
      title: 'NO_PRODUCTS',
      description: '',
      needs_enrichment: false,
      enrichment_reason: 'empty_batch',
      store_name: 'REPLACE_WITH_STORE_NAME',
    },
  }];
}
return output;

const all = $('Dedupe & Flag Enrichment Needs').all().map((i) => i.json);
const enriched = $('Sheet: Append Catalog_QA').all().map((i) => i.json);
const total = all.length;
const needed = all.filter((r) => r.needs_enrichment).length;
const skipped = total - needed;
return [{
  json: {
    ok: true,
    batch_received: total,
    enriched_count: enriched.length,
    skipped_count: skipped,
    message: 'Batch processed. Review Catalog_QA sheet before publishing.',
    store_name: 'REPLACE_WITH_STORE_NAME',
  },
}];

const src = $input.item.json;
const out = src.output || src;
const tags = Array.isArray(out.suggested_tags) ? out.suggested_tags : [];
let confidence = Number(out.confidence_score);
if (Number.isNaN(confidence)) confidence = 0.5;
return {
  json: {
    enrich_id: src.enrich_id,
    received_at: src.received_at,
    product_id: src.product_id,
    sku: src.sku,
    handle: src.handle,
    original_title: src.title,
    original_description: src.description,
    enrichment_reason: src.enrichment_reason,
    seo_title: out.seo_title || src.title,
    description_html: out.description_html || src.description,
    meta_description: out.meta_description || '',
    suggested_tags: tags.join(', '),
    confidence_score: confidence,
    status: 'pending_review',
    reviewed_by: '',
    reviewed_at: '',
    published_at: '',
    store_name: src.store_name || 'REPLACE_WITH_STORE_NAME',
  },
};
